from PIL import Image

def blobs(path, thresh=80, ymin=360):
    im = Image.open(path)
    pix = im.load()
    w,h = im.size
    pts = []
    for y in range(ymin, h):
        for x in range(w):
            r,g,b = pix[x,y]
            if (r+g+b)//3 < thresh:
                pts.append((x,y))
    if not pts:
        return None
    cx = sum(p[0] for p in pts)/len(pts)
    cy = sum(p[1] for p in pts)/len(pts)
    xs = [p[0] for p in pts]; ys = [p[1] for p in pts]
    return len(pts), cx, cy, min(xs), max(xs), min(ys), max(ys)

